    {
      "task": "find lapis_block",
      "description": "Player has found and is near the lapis_block pillar landmark",
      "rules": [
        {
          "rule_type": "position_inside_box",
          "parameters": {
            "x_min": "~2",
            "x_max": "~8",
            "y_min": "~-1",
